      r.agents.map((a) => `${a.installed ? pc.green("✓") : pc.dim("✗")} ${a.name}`).join("   ")
  );

  if (r.health.length > 0) {
    ui.blank();
    ui.heading("Health");
    for (const h of r.health) {
      const suffix = h.origin === "authored" ? "" : pc.dim(`  (${h.origin})`);
      const primary = h.errors[0] ?? h.warnings[0];
      renderCheck(
        h.status === "pass" ? "pass" : h.status,
        `${h.path}${suffix}${primary ? " — " + primary.text : ""}`,
      );
      if (h.status !== "pass") {
        const url =
          primary?.docUrl ??
          getFindingDocUrl({ code: primary?.code });
        if (url) ui.dim(`      Docs: ${url}`);
      }
    }
    ui.blank();
    ui.dim(`  ${r.summary.passed} passed · ${r.summary.failed} failed · ${r.summary.warnings} warnings`);
  }

  if (r.contradictions.length > 0) {
    ui.blank();
    ui.heading("Contradictions");
    for (const c of r.contradictions) {
      const mark = c.severity === "conflict" ? "fail" : "warn";
      const where = c.sources.map((s) => s.file).join(", ");
      renderCheck(mark, `${c.message}${where ? pc.dim(`  (${where})`) : ""}`);
    }
    ui.blank();
    ui.dim(
      `  ${r.contradictions.filter((c) => c.severity === "conflict").length} conflicts · ${r.contradictions.filter((c) => c.severity === "gap").length} gaps`,
    );
  }

  if (r.shadows.length > 0) {
    ui.blank();
    ui.heading("Name collisions");
    for (const s of r.shadows) {
      renderCheck(
        "warn",
        `${s.name}  ${pc.dim(s.paths.join("  →  "))}  ${pc.dim("(first wins for Grok)")}`,
      );
      const shadowDocs = getFindingDocUrl({ code: "E-SCAN-SHADOW" });
      if (shadowDocs) ui.dim(`      Docs: ${shadowDocs}`);
    }
  }

  if (r.overlaps.length > 0) {
    ui.blank();
    ui.heading("Skill overlap");
    for (const o of r.overlaps) {
      renderCheck("warn", `${o.a}  ↔  ${o.b}  ${pc.dim(o.reason)}`);
      const docs = getFindingDocUrl({ code: "E-SCAN-OVERLAP" });
      if (docs) ui.dim(`      Docs: ${docs}`);
    }
  }

  if (r.mcpCollisions.length > 0) {
    ui.blank();
    ui.heading("MCP name collisions");
    for (const c of r.mcpCollisions) {
      renderCheck("warn", `${c.a}  ↔  ${c.b}  ${pc.dim(c.reason)}`);
      const docs = getFindingDocUrl({ code: "E-SCAN-MCP" });
      if (docs) ui.dim(`      Docs: ${docs}`);
    }
  }

  ui.blank();
  ui.heading("Intelligence");
  renderCheck("ok", r.intelligence.detail);
  {
    const inst = r.intelligence.install;
    const mark =
      inst.status === "fail" ? "fail" : inst.status === "warn" ? "warn" : inst.status === "ok" ? "ok" : "pass";
    // skip (source/unsupported) → dim pass-style line, not an alarm
    renderCheck(mark === "pass" ? "ok" : mark, inst.detail + (inst.hint && inst.status === "fail" ? pc.dim(` — ${inst.hint}`) : ""));
  }
  {
    const b = r.intelligence.contextBudget;
    if (b.status !== "empty") {
      renderCheck(b.status === "warn" ? "warn" : "ok", b.summary);
      if (b.hint) ui.dim(`      ${b.hint}`);
    }
  }

  if (r.suggestions.length > 0) {
    ui.blank();
    ui.heading("Next");
    r.suggestions.forEach((s, i) => {
      ui.info(`  ${i + 1}. ${pc.bold(s.command.padEnd(28))} ${pc.dim(s.title)}`);
    });
  }
  ui.blank();
}

export default defineCommand({
  meta: {
    name: "scan",
    description: [
      "Scan the repo: agent surfaces, skill health, next actions",
      "",
      "Examples:",
      "  dora",
      "  dora --json",
      "  dora --yes",
      "Exit: 0 clean · 1 issues · 2 could not run",
    ].join("\n"),
  },
  args: {
    format: { type: "string", description: "Output format: table | json", default: "table" },
    json: { type: "boolean", description: "Alias for --format json", default: false },
    ci: { type: "boolean", description: "Machine mode (implies --format json)", default: false },
    cwd: { type: "string", description: "Directory to scan (CI / coding agents)" },
    yes: {
      type: "boolean",
      description: "Skip the proceed/stop prompt (agents / scripts)",
      default: false,
      alias: "y",
    },
  },
  async run({ args }) {
    const mode = resolveOutputMode({ format: args.format as string, ci: args.ci as boolean, json: args.json as boolean });
    const dir = (args.cwd as string) || process.cwd();
    const yes = Boolean(args.yes);

    if (shouldConfirmScan({ format: mode.format, yes, agent: isAgentCaller() })) {
      const go = await confirmScanProceed(dir);
      if (!go) await exit(0);
    }

    try {
      const result = await runScan(dir);
      if (mode.format === "json") outJson(result);
      else renderHuman(result);
      const hasConflicts = result.contradictions.some((c) => c.severity === "conflict");
      await exit(result.summary.failed > 0 || hasConflicts ? 1 : 0);
    } catch (e) {
      emitError(e, mode);
      await exit(2);
    }
  },
});

